#define IDV_FAST_MATH_ONE_BITS 0x3F800000

//////////////////////////////////////////////////////////////////////
//  _idv_finv definition
//

// r = 1/p
#define _idv_finv(r,p)                                                       \
{                                                                            \
    int _i = 2 * IDV_FAST_MATH_ONE_BITS - *(int*)&(p);                      \
    r = *(float*)&_i;                                                       \
    r = r * (2.0f - (p) * r);                                                \
}

//////////////////////////////////////////////////////////////////////
//  _idv_int definition
//

__inline int _idv_int(float fValue)
{
    double dTemp = fValue + c_dIdvFastMathFloatConversionMagicNumber;
    return (*((long*)&dTemp)) - 0x80000000;


//  fValue += (1 << 23);
//  return (*((int*)&fValue)) & 0x7fffff;

//  return int(fValue);
}


//////////////////////////////////////////////////////////////////////
//  _idv_cosD definition
//

__inline float _idv_cosD(float fValueDegrees)
{
    return g_fIdvCosTable[_idv_int(fValueDegrees * c_dIdvFastMathConstantForDegrees) & 4095];
}


//////////////////////////////////////////////////////////////////////
//  _idv_sinD definition
//

__inline float _idv_sinD(float fValueDegrees)
{
    return g_fIdvSinTable[_idv_int(fValueDegrees * c_dIdvFastMathConstantForDegrees) & 4095];
}


//////////////////////////////////////////////////////////////////////
//  _idv_tanD definition
//

__inline float _idv_tanD(float fValueDegrees)
{
    return g_fIdvTanTable[_idv_int(fValueDegrees * c_dIdvFastMathConstantForDegrees) & 4095];
}


//////////////////////////////////////////////////////////////////////
//  _idv_cos definition
//

__inline float _idv_cos(float fRadians)
{
    return g_fIdvCosTable[_idv_int(fRadians * c_dIdvFastMathConstantForRadians) & 4095];
}


//////////////////////////////////////////////////////////////////////
//  _idv_acos definition
//

__inline float _idv_acos(float fValue)
{
    return g_fIdvACosTable[(unsigned int)((fValue + 2.0f) * 2048.0f) & 4095];
}


//////////////////////////////////////////////////////////////////////
//  _idv_sin definition
//

__inline float _idv_sin(float fRadians)
{
    return g_fIdvSinTable[_idv_int(fRadians * c_dIdvFastMathConstantForRadians) & 4095];
}


//////////////////////////////////////////////////////////////////////
//  _idv_tan definition
//

__inline float _idv_tan(float fRadians)
{
    return g_fIdvTanTable[_idv_int(fRadians * c_dIdvFastMathConstantForRadians) & 4095];
}


//////////////////////////////////////////////////////////////////////
//  _idv_sqrt1 definition
//

__inline float _idv_sqrt1(float fVal)
{
    int i = ((*(int*)&fVal) >> 1 ) + 0x1fc00000;
    return *(float*)&i;
}
